def service_tab_icon(service_key: str) -> str:
    """Quasar `icon` value: embedded SVG as data URI (for `ui.tab(..., icon=...)`)."""
    svg = SERVICE_BRAND_SVG[service_key]
    return "img:data:image/svg+xml;charset=UTF-8," + quote(svg, safe="")
